```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The precondition guarantees len(reply.text) <= 100000, so the text
        // is forwarded unchanged. The node sends exactly once, so it never
        // delivers a duplicate reply to the session.
        let confirmation: DeliveryConfirmation = response_channel::send(&reply.text);

        // The session identity comes from the host channel. The node never
        // fabricates it. If the host reports that the reply was not delivered,
        // or gives no session identity, the node cannot meet its postconditions
        // honestly. It traps (panic = "abort") so it never returns an output
        // that breaks `delivered == true` or `present(session_id)`.
        if !confirmation.delivered {
            panic!("response channel did not accept the reply");
        }
        if confirmation.session.is_empty() {
            panic!("response channel returned no session identity");
        }

        DeliveryConfirmation {
            session: confirmation.session,
            delivered: true,
        }
    }
}

export!(Node);
```

